              onClick={e => {
                e.stopPropagation()
                toggle(page.id)
              }}
              className="shrink-0 w-5 h-5 flex items-center justify-center rounded text-dark-text-tertiary hover:text-dark-text-primary hover:bg-dark-bg-primary/60"
